import math

# 1. Verify phi(16)
def phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

phi_16 = phi(16)
print(f"phi(16) = {phi_16}")

# 2. Calculate ord_16(3)
def order(base, modulus):
    if math.gcd(base, modulus) != 1:
        return None # Order is undefined if not coprime

    # Search up to phi(modulus)
    phi_m = phi(modulus)
    for k in range(1, phi_m + 1):
        if pow(base, k, modulus) == 1:
            return k
    return None

ord_16_3 = order(3, 16)
print(f"ord_16(3) = {ord_16_3}")
